"""Direct live refresh: compare persisted legal checkpoint with independent production replay."""
import argparse,asyncio,datetime,json
from playwright.async_api import async_playwright
from test_duel_browser import ROOT,KEY,FIELDS,snap,load,watch,Pilot,Driver,begin,complete
async def main(args):
 out=ROOT/args.out;out.parent.mkdir(parents=True,exist_ok=True);errors=[];bad=[];failed=[];report={'testedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'url':args.url};pilot=await Pilot().start()
 async with async_playwright() as pw:
  b=await pw.chromium.launch()
  try:
   ctx=await b.new_context(viewport={'width':1360,'height':1100});p=await ctx.new_page();watch(p,errors,bad,failed);d=await Driver(p).start();await load(p,args.url);await begin(p,d);await p.keyboard.press('u');await p.wait_for_timeout(120);await d.command({'kind':'move','value':1});before=await snap(p);assert before['state']=='playing' and before['player']['action']['kind']=='heavy';await load(p,args.url,True);after=await snap(p);cp=await p.evaluate('JSON.parse(localStorage.getItem('+json.dumps(KEY)+')).resume');assert after['state']=='paused' and after['player']['move']==0 and not after['player']['guard'] and not after['held']
   source="import fs from 'node:fs';import{restore,snapshot}from './games/duel/engine.mjs';console.log(JSON.stringify(snapshot(restore(JSON.parse(fs.readFileSync(0,'utf8'))))))";proc=await asyncio.create_subprocess_exec('node','--input-type=module','-e',source,cwd=str(ROOT),stdin=asyncio.subprocess.PIPE,stdout=asyncio.subprocess.PIPE,stderr=asyncio.subprocess.PIPE);stdout,stderr=await proc.communicate(json.dumps(cp).encode());assert proc.returncode==0,stderr.decode();expected=json.loads(stdout);assert all(after[k]==expected[k] for k in FIELDS);await p.wait_for_timeout(500);waited=await snap(p);assert all(waited[k]==after[k] for k in FIELDS);await d.release();await p.locator('#resume').click();end,_,_=await complete(p,pilot,d);assert end['state']=='won' and end['player']['hp']>0 and end['enemy']['hp']==0;await d.release();assert not errors and not bad and not failed;report.update(passed=True,method='Actual live heavy start plus held movement then direct reload, with no manual pause. Pagehide may occur after additional legitimate ticks; persisted checkpoint is independently replayed in a separate production-engine Node instance. No browser state writes.',beforeRefresh={k:before[k] for k in FIELDS},savedCheckpoint=cp,restored={k:after[k] for k in FIELDS},exactFields=FIELDS,continuedWin={'hp':end['player']['hp'],'score':end['score'],'stats':end['stats'],'actualLog':end['log']});await ctx.close();print(json.dumps({'passed':True,'beforeTick':before['ticks'],'savedTick':cp['ticks'],'restoredPhase':after['playerPhase'],'winHP':end['player']['hp']}))
  except Exception as e:report['error']=type(e).__name__+': '+str(e)[:1400];raise
  finally:report.update(consoleErrors=errors,badResponses=bad,requestFailures=failed);out.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8');await b.close();await pilot.close()
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--url',default='https://yydshly.github.io/classic-games-atlas/games/duel/');a.add_argument('--out',default='docs/duel-qa/public-refresh.json');asyncio.run(main(a.parse_args()))
